    }
  },
  "signal_basis": {
    "component_id": "C036.signal_basis",
    "value": "Removals have explicit operational counterparts. Repeated testing retains a smaller configuration that reproduces lateness, while specified further removals cease to reproduce it.",
    "scope": "The selected replay case, with equipment, agreed start deadline and other test conditions fixed; baseline and reductions use the same repetition rule, and inconsistent or uncertain outcomes remain unresolved.",
